using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Identity;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Credit;
using Shop.Modules.Identity;
using Shop.Modules.Inventory;
using Shop.Modules.Sales;
using Xunit;
using IdentityContext=Shop.Modules.Identity.IdentityDbContext;
namespace Shop.SqlTests;
public sealed class CreditApplicationSqlTests(SqlFixture sql):IClassFixture<SqlFixture>
{
    private static string Id()=>Guid.NewGuid().ToString("N");
    private async Task<(HttpClient Client,string Owner)> Customer(){await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="creditqa"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);var signed=await scope.ServiceProvider.GetRequiredService<AuthService>().PasswordAsync(new(name,sql.Password),true,true,false,default);var client=sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Authorization=new("Bearer",signed.AccessToken);client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");return(client,user.Id.ToUpperInvariant());}
    private async Task<HttpClient> Staff(string role){await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="creditstaff"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(user,role)).Succeeded);var client=sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");client.DefaultRequestHeaders.Add("X-Sayman-Client","admin");client.DefaultRequestHeaders.Add("X-Sayman-Admin","1");var pending=await Read(await client.PostAsJsonAsync("/api/auth/password",new{Identifier=name,Password=sql.Password}));client.DefaultRequestHeaders.Authorization=new("Bearer",pending["accessToken"]!.GetValue<string>());using(var forbidden=await client.GetAsync("/api/admin/credit/applications"))Assert.Equal(HttpStatusCode.Forbidden,forbidden.StatusCode);var setup=await Read(await client.PostAsJsonAsync("/api/auth/mfa/setup",new{}));client.DefaultRequestHeaders.Authorization=new("Bearer",setup["accessToken"]!.GetValue<string>());var signed=await Read(await client.PostAsJsonAsync("/api/auth/mfa/verify",new{Code=Totp.Code(setup["secret"]!.GetValue<string>(),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30)}));client.DefaultRequestHeaders.Authorization=new("Bearer",signed["accessToken"]!.GetValue<string>());return client;}
    private async Task<CreditApplicationPlanOption> Plan(){await using var scope=sql.Factory.Services.CreateAsyncScope();var service=scope.ServiceProvider.GetRequiredService<CreditPlanService>();var id=await service.SaveAsync(null,new("طرح ساختگی آزمون پرونده","Synthetic application QA plan",6,3000,2500,1,true,null,null,[],null,10),default);var row=await scope.ServiceProvider.GetRequiredService<CreditDbContext>().Plans.AsNoTracking().SingleAsync(x=>x.Id==id);return new(row.Id,Convert.ToBase64String(row.Version),row.NameFa,row.NameEn,row.Months,row.MarkupBasisPoints,row.DownPaymentBasisPoints,row.IntervalMonths,row.RoundingUnitRial.ToString(System.Globalization.CultureInfo.InvariantCulture),null,null,0);}
    private static CreateCreditApplicationInput Input(CreditApplicationPlanOption plan)=>new(plan.Id,plan.Version,"9007199254740993","fa");
    private static async Task<JsonNode> Read(HttpResponseMessage response,string? capture=null){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");if(capture is not null&&Environment.GetEnvironmentVariable("SHOP_CREDIT_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,capture+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,capture+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,cacheControl=response.Headers.CacheControl?.ToString()}));}return JsonNode.Parse(raw)!;}}
    private static string Value(JsonNode node,string key)=>node[key]!.GetValue<string>();
    [Fact]public async Task PrivateDraftKeepsExactHistoricalPlanRialAndReceiptsWithoutCreatingOrderOrStockEntitlement()
    {
        var person=await Customer();using var customer=person.Client;var plan=await Plan();await Read(await customer.GetAsync("/api/credit/plans"),"plans");var command=Id();var path="/api/credit/applications/commands/"+command;var input=Input(plan);var created=await Read(await customer.PostAsJsonAsync(path,input),"created");var application=created["application"]!;var id=Value(application,"id");Assert.Equal(input.RequestedAmountRial,Value(application,"requestedAmountRial"));Assert.DoesNotContain(person.Owner,created.ToJsonString(),StringComparison.OrdinalIgnoreCase);
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var row=await db.Applications.AsNoTracking().SingleAsync(x=>x.Id==id);Assert.Equal(9007199254740993L,row.RequestedAmountRial);Assert.DoesNotContain(plan.NameFa,Encoding.UTF8.GetString(row.ProtectedPlan));var stored=await db.Plans.SingleAsync(x=>x.Id==plan.Id);stored.NameFa="نام و درصدِ تغییرکردهٔ ساختگی";stored.MarkupBasisPoints=999;stored.Enabled=false;await db.SaveChangesAsync();Assert.Empty(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.ToArrayAsync());Assert.Empty(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Reservations.ToArrayAsync());}
        var detail=await Read(await customer.GetAsync("/api/credit/applications/"+id),"detail");Assert.Equal(plan.NameFa,Value(detail["plan"]!,"nameFa"));Assert.Equal("10",Value(detail["plan"]!,"roundingUnitRial"));Assert.Equal(3000,detail["plan"]!["markupBasisPoints"]!.GetValue<int>());Assert.False(detail["canSubmit"]!.GetValue<bool>());Assert.Equal("credit_submission_not_configured",detail["blockers"]![0]!.GetValue<string>());
        var replay=await Read(await customer.PostAsJsonAsync(path,input),"create-replay");Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(application.ToJsonString(),replay["application"]!.ToJsonString());var cancelled=await Read(await customer.PutAsJsonAsync($"/api/credit/applications/{id}/cancel/{Id()}",new CancelCreditApplicationInput(Value(application,"version"))),"cancelled");Assert.Equal("Cancelled",Value(cancelled["application"]!,"state"));var historical=await Read(await customer.GetAsync("/api/credit/commands/"+command),"historical-receipt");Assert.Equal("Draft",Value(historical["application"]!,"state"));await Read(await customer.GetAsync("/api/credit/applications?state=Cancelled"),"page");
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().ApplicationEvents.CountAsync(x=>x.ApplicationId==id));Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.ActorId==person.Owner&&x.Action=="CREDIT_APPLICATION"));}
    }
    [Fact]public async Task ForeignCustomerAndExistingFinanceReadersCannotSeePrivateApplicationsWhileExplicitReviewerMfaCan()
    {
        var person=await Customer();using var customer=person.Client;var foreign=await Customer();using var other=foreign.Client;var plan=await Plan();var command=Id();var created=await Read(await customer.PostAsJsonAsync("/api/credit/applications/commands/"+command,Input(plan)));var id=Value(created["application"]!,"id");using(var denied=await other.GetAsync("/api/credit/applications/"+id))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);using(var denied=await other.GetAsync("/api/credit/commands/"+command))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);Assert.Empty((await Read(await other.GetAsync("/api/credit/applications")))["items"]!.AsArray());
        foreach(var role in new[]{"CatalogManager","FinanceManager","SupportAgent"}){using var staff=await Staff(role);using var denied=await staff.GetAsync("/api/admin/credit/applications/"+id);Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}using(var reviewer=await Staff("CreditReviewer")){var visible=await Read(await reviewer.GetAsync("/api/admin/credit/applications/"+id),"reviewer-detail");Assert.Equal(id,Value(visible["application"]!,"id"));}
        using(var anonymous=sql.Factory.CreateClient(new(){HandleCookies=false})){using var denied=await anonymous.GetAsync("/api/credit/applications");Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);Assert.Contains("no-store",denied.Headers.CacheControl!.ToString());Assert.Contains("noindex",denied.Headers.GetValues("X-Robots-Tag").Single());}
        using(var unknown=await customer.PostAsJsonAsync("/api/credit/applications/commands/"+Id(),new{planId=plan.Id,planVersion=plan.Version,requestedAmountRial="100",locale="fa",approved=true}))Assert.Equal(HttpStatusCode.BadRequest,unknown.StatusCode);using(var badQuery=await customer.GetAsync("/api/credit/applications?ownerId="+person.Owner))Assert.Equal(HttpStatusCode.BadRequest,badQuery.StatusCode);customer.DefaultRequestHeaders.Remove("Origin");customer.DefaultRequestHeaders.Add("Origin","https://wrong.example");using(var origin=await customer.GetAsync("/api/credit/applications/"+id))Assert.Equal(HttpStatusCode.Forbidden,origin.StatusCode);
    }
    [Fact]public async Task AuditFailureRollsBackTheWholeDraftAndHistoryAndItsGuardedMigrationCannotDeleteRetainedApplications()
    {
        var person=await Customer();using var customer=person.Client;var plan=await Plan();var command=Id();var path="/api/credit/applications/commands/"+command;
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<IdentityContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_CreditApplicationAuditFailure CHECK ([Action]<>'CREDIT_APPLICATION')");}
        try{using var denied=await customer.PostAsJsonAsync(path,Input(plan));Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_CreditApplicationAuditFailure");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.Empty(await db.Applications.Where(x=>x.OwnerId==person.Owner).ToArrayAsync());Assert.Empty(await db.ApplicationCommands.Where(x=>x.CommandId==command).ToArrayAsync());Assert.Empty(await db.ApplicationEvents.Where(x=>x.ActorId==person.Owner).ToArrayAsync());}
        await Read(await customer.PostAsJsonAsync(path,Input(plan)));await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var migrationSource=(await db.Database.GetAppliedMigrationsAsync()).ToArray();var error=await Assert.ThrowsAsync<SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261022121338_ChequeRoundingUnit"));Assert.Equal(51000,error.Number);await db.Database.MigrateAsync();Assert.Equal(migrationSource,await db.Database.GetAppliedMigrationsAsync());Assert.False(db.Database.HasPendingModelChanges());Assert.Single(await db.Applications.Where(x=>x.OwnerId==person.Owner).ToArrayAsync());}
    }
    [Fact]public async Task SameCommandRaceHasOneAuditChangedInputConflictsAndOnlyOneConcurrentCancellationWins()
    {
        var person=await Customer();using var customer=person.Client;var plan=await Plan();var command=Id();var path="/api/credit/applications/commands/"+command;var input=Input(plan);var responses=await Task.WhenAll(customer.PostAsJsonAsync(path,input),customer.PostAsJsonAsync(path,input));var results=await Task.WhenAll(responses.Select(x=>Read(x)));Assert.Single(results,x=>!x["replayed"]!.GetValue<bool>());Assert.Single(results,x=>x["replayed"]!.GetValue<bool>());using(var conflict=await customer.PostAsJsonAsync(path,input with{RequestedAmountRial="9007199254740994"}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);
        var app=results[0]["application"]!;var id=Value(app,"id");var cancel=new CancelCreditApplicationInput(Value(app,"version"));var cancelled=await Task.WhenAll(customer.PutAsJsonAsync($"/api/credit/applications/{id}/cancel/{Id()}",cancel),customer.PutAsJsonAsync($"/api/credit/applications/{id}/cancel/{Id()}",cancel));Assert.Single(cancelled,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(cancelled,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var response in cancelled)response.Dispose();await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().ApplicationEvents.CountAsync(x=>x.ApplicationId==id));Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.CountAsync(x=>x.ActorId==person.Owner&&x.Action=="CREDIT_APPLICATION"));
    }
}
